"use client";
import { FormEvent, useEffect, useMemo, useState } from "react";
import { api, ApiError } from "@/lib/api-client";
import { BarChart3, Megaphone, MousePointerClick, Eye, CalendarDays, TrendingUp, RotateCcw, MapPin, ShieldCheck } from "lucide-react";

type Plan={durationDays:number;price:number;label?:string};
type Campaign={id:string;name:string;objective:string;target_type:string;target_id?:string|null;target_category?:string|null;target_location?:string|null;duration_days:number;price:number;status:string;start_at?:string;end_at?:string};
type Analytics={metrics:{impressions:number;clicks:number;ctr:number;destinationViews:number;checkoutStarts:number;purchases:number;bookings:number;conversions:number;revenueGenerated:number;adSpend:number;roas:number;conversionRate:number}};
type SeriesPoint={timestamp:string;impressions:number;clicks:number;destinationViews:number;checkoutStarts:number;purchases:number;bookings:number};
const RANGES={"24h":"24 hours","7d":"7 days","30d":"30 days"} as const;
const OBJECTIVE_HELP:Record<string,string>={STORE_VISITS:"Best when you want more people visiting your store.",PRODUCT_VIEWS:"Best for getting attention on one product.",SERVICE_BOOKINGS:"Best for services that depend on bookings.",ORDERS:"Best when your main goal is completed orders.",STORE_PROMOTION:"Best for introducing or growing your store.",SPECIAL_OFFER:"Best for discounts, launches and limited offers."};
function money(v:number){return `₦${Math.round(v).toLocaleString()}`}
function countdown(end?:string){if(!end)return "Not started";const ms=new Date(end).getTime()-Date.now();if(ms<=0)return "Expired";const d=Math.floor(ms/86400000),h=Math.floor(ms%86400000/3600000);return d?`${d}d ${h}h left`:`${h}h left`}
export default function AdsPage(){
 const[plans,setPlans]=useState<Plan[]>([]),[campaigns,setCampaigns]=useState<Campaign[]>([]),[selected,setSelected]=useState<Campaign|null>(null),[analytics,setAnalytics]=useState<Analytics|null>(null),[series,setSeries]=useState<SeriesPoint[]>([]),[range,setRange]=useState<keyof typeof RANGES>("24h"),[busy,setBusy]=useState(false),[loading,setLoading]=useState(false),[error,setError]=useState("");
 const[form,setForm]=useState({name:"",objective:"STORE_VISITS",targetType:"STORE",targetId:"",targetCategory:"",targetLocation:"",durationDays:"7"});
 async function load(){try{const[p,c]=await Promise.all([api.get<{plans:Plan[]}>("/api/ads/plans"),api.get<{campaigns:Campaign[]}>("/api/ads/campaigns")]);setPlans(p.plans);setCampaigns(c.campaigns)}catch(e){setError(e instanceof ApiError?e.message:"Unable to load Ad Centre")}}
 useEffect(()=>{void load()},[]);
 async function create(e:FormEvent){e.preventDefault();setBusy(true);setError("");try{const r=await api.post<{checkoutUrl:string}>("/api/ads/campaigns",{...form,durationDays:Number(form.durationDays),targetId:form.targetId||undefined,targetCategory:form.targetCategory||undefined,targetLocation:form.targetLocation||undefined});window.location.href=r.checkoutUrl}catch(e){setError(e instanceof ApiError?e.message:"Unable to start campaign");setBusy(false)}}
 async function inspect(c:Campaign,r=range){setSelected(c);setLoading(true);setError("");try{const[a,s]=await Promise.all([api.get<Analytics>(`/api/ads/campaigns/${c.id}/analytics`),api.get<{series:SeriesPoint[]}>(`/api/ads/campaigns/${c.id}/analytics/series?range=${r}`)]);setAnalytics(a);setSeries(s.series)}catch(e){setError(e instanceof ApiError?e.message:"Unable to load analytics")}finally{setLoading(false)}}
 function boost(c:Campaign){setForm({name:`${c.name} — Boost`,objective:c.objective,targetType:c.target_type,targetId:c.target_id??"",targetCategory:c.target_category??"",targetLocation:c.target_location??"",durationDays:String(c.duration_days)});window.scrollTo({top:0,behavior:"smooth"})}
 const max=useMemo(()=>Math.max(1,...series.map(x=>x.impressions)),[series]);
 const selectedPlan=plans.find(p=>String(p.durationDays)===form.durationDays);
 return <div className="shell py-8"><div><p className="text-xs font-semibold uppercase tracking-[.16em] text-ember-600">TTFL Advertising</p><h1 className="mt-1 text-2xl font-bold">Ad Centre</h1><p className="mt-1 max-w-2xl text-sm text-graphite-600 dark:text-graphite-400">Promote your store, products and services with simple fixed-duration campaigns and live performance analytics.</p></div>
 <div className="mt-6 grid gap-3 sm:grid-cols-4">{plans.map(p=><button key={p.durationDays} type="button" onClick={()=>setForm(x=>({...x,durationDays:String(p.durationDays)}))} className={`rounded-card border p-4 text-left ${form.durationDays===String(p.durationDays)?"border-ember-600 ring-2 ring-ember-100":"border-graphite-200 dark:border-graphite-700"}`}><div className="flex justify-between"><span className="text-sm font-semibold">{p.durationDays} day{p.durationDays===1?"":"s"}</span>{p.label&&<span className="text-[10px] font-bold uppercase text-ember-600">{p.label}</span>}</div><p className="mt-2 text-xl font-bold">{money(p.price)}</p></button>)}</div>
 <div className="mt-6 grid gap-6 lg:grid-cols-[1.05fr_.95fr]"><form onSubmit={create} className="rounded-card border border-graphite-200 bg-white p-6 dark:border-graphite-700 dark:bg-graphite-900"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-card bg-ember-100 text-ember-700"><Megaphone className="h-5 w-5"/></span><div><h2 className="font-bold">Create campaign</h2><p className="text-xs text-graphite-500">Paid campaigns are reviewed before public placement.</p></div></div><div className="mt-5 space-y-4"><label className="block"><span className="text-sm font-semibold">Campaign name</span><input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})} className="mt-2 field" placeholder="Weekend service promotion"/></label><label className="block"><span className="text-sm font-semibold">Campaign goal</span><select value={form.objective} onChange={e=>setForm({...form,objective:e.target.value})} className="mt-2 field"><option value="STORE_VISITS">Store visits</option><option value="PRODUCT_VIEWS">Product views</option><option value="SERVICE_BOOKINGS">Service bookings</option><option value="ORDERS">Orders</option><option value="STORE_PROMOTION">Store promotion</option><option value="SPECIAL_OFFER">Special offer</option></select><p className="mt-1 text-xs text-graphite-500">{OBJECTIVE_HELP[form.objective]}</p></label><label className="block"><span className="text-sm font-semibold">Promote</span><select value={form.targetType} onChange={e=>setForm({...form,targetType:e.target.value})} className="mt-2 field"><option value="STORE">My store</option><option value="PRODUCT">A product</option><option value="SERVICE">A service</option><option value="COMING_SOON">Coming Soon listing</option></select></label><label className="block"><span className="text-sm font-semibold">Target ID <span className="font-normal text-graphite-400">(not needed for stores)</span></span><input value={form.targetId} onChange={e=>setForm({...form,targetId:e.target.value})} className="mt-2 field" placeholder="Product or service ID"/></label><div className="grid gap-4 sm:grid-cols-2"><label><span className="text-sm font-semibold">Category</span><input value={form.targetCategory} onChange={e=>setForm({...form,targetCategory:e.target.value})} className="mt-2 field" placeholder="Phones & Tablets"/></label><label><span className="flex items-center gap-1 text-sm font-semibold"><MapPin className="h-3.5 w-3.5"/>Location</span><input value={form.targetLocation} onChange={e=>setForm({...form,targetLocation:e.target.value})} className="mt-2 field" placeholder="Lagos"/></label></div>{error&&<p className="text-sm font-medium text-ember-600">{error}</p>}<button disabled={busy} className="w-full rounded-card bg-ember-600 px-4 py-3 text-sm font-semibold text-white disabled:opacity-60">{busy?"Opening payment…":`Pay ${money(selectedPlan?.price??0)} and submit`}</button></div></form>
 <section className="rounded-card border border-graphite-200 bg-white p-6 dark:border-graphite-700 dark:bg-graphite-900"><div className="flex items-center justify-between"><div><h2 className="font-bold">Campaign analytics</h2><p className="text-xs text-graphite-500">Revenue, return on spend and conversions.</p></div><BarChart3 className="h-5 w-5 text-graphite-400"/></div>{selected&&analytics?<><div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-3">{[[Eye,"Impressions",analytics.metrics.impressions],[MousePointerClick,"Clicks",analytics.metrics.clicks],[BarChart3,"CTR",`${analytics.metrics.ctr}%`],[TrendingUp,"Revenue",money(analytics.metrics.revenueGenerated)],[TrendingUp,"Ad spend",money(analytics.metrics.adSpend)],[TrendingUp,"ROAS",`${analytics.metrics.roas}x`],[CalendarDays,"Conversions",analytics.metrics.conversions],[TrendingUp,"Conversion rate",`${analytics.metrics.conversionRate}%`],[Eye,"Checkout starts",analytics.metrics.checkoutStarts]].map(([I,l,v]:any)=><div key={l} className="rounded-card bg-cloud-50 p-4 dark:bg-graphite-800"><I className="h-4 w-4 text-graphite-500"/><p className="mt-3 text-xl font-bold">{v}</p><p className="text-xs text-graphite-500">{l}</p></div>)}</div><div className="mt-5 rounded-card border border-graphite-200 p-4 dark:border-graphite-700"><p className="text-sm font-bold">Campaign status</p><div className="mt-2 flex flex-wrap items-center gap-2 text-xs"><span className="rounded-full bg-cloud-100 px-2.5 py-1 font-bold">{selected.status}</span><span className="text-graphite-500">{selected.status==="ACTIVE"?countdown(selected.end_at):selected.status==="PENDING_REVIEW"?"Awaiting TTFL review":"Not currently running"}</span></div></div><div className="mt-5 flex items-center justify-between gap-3"><div><p className="text-sm font-bold">Performance</p><p className="text-xs text-graphite-500">Impressions and clicks</p></div><div className="flex rounded-card border border-graphite-200 p-1">{(Object.keys(RANGES) as Array<keyof typeof RANGES>).map(r=><button key={r} type="button" onClick={()=>{setRange(r);void inspect(selected,r)}} className={`rounded px-2.5 py-1.5 text-xs font-semibold ${range===r?"bg-graphite-900 text-white":"text-graphite-500"}`}>{RANGES[r]}</button>)}</div></div><div className="mt-4 rounded-card bg-cloud-50 p-4 dark:bg-graphite-950">{loading?<p className="py-10 text-center text-sm text-graphite-500">Updating analytics…</p>:<div className="flex h-36 items-end gap-1">{series.map(p=><div key={p.timestamp} className="flex h-full flex-1 items-end gap-px" title={`${new Date(p.timestamp).toLocaleString()} · ${p.impressions} impressions · ${p.clicks} clicks`}><span className="w-1/2 rounded-t bg-ember-500" style={{height:`${Math.max(4,p.impressions/max*100)}%`}}/><span className="w-1/2 rounded-t bg-graphite-400" style={{height:`${p.clicks?Math.max(2,p.clicks/max*100):0}%`}}/></div>)}</div>}</div></>:<p className="mt-8 text-center text-sm text-graphite-500">Select a campaign below to view analytics.</p>}
 <div className="mt-6 space-y-2">{campaigns.map(c=><div key={c.id} className="rounded-card border border-graphite-200 p-4 dark:border-graphite-700"><button onClick={()=>void inspect(c)} className="w-full text-left"><div className="flex items-center justify-between gap-3"><span className="font-semibold">{c.name}</span><span className="text-xs font-semibold">{c.status}</span></div><p className="mt-1 text-xs text-graphite-500">{c.duration_days} days · {c.target_type} · {money(Number(c.price))}</p>{c.status==="ACTIVE"&&<p className="mt-1 text-xs font-semibold text-verified-700">{countdown(c.end_at)}</p>}{c.status==="PENDING_REVIEW"&&<p className="mt-1 flex items-center gap-1 text-xs font-semibold text-graphite-500"><ShieldCheck className="h-3.5 w-3.5"/>Awaiting TTFL review</p>}</button>{["EXPIRED","CANCELLED","PAUSED","REJECTED"].includes(c.status)&&<button type="button" onClick={()=>boost(c)} className="mt-3 inline-flex items-center gap-1.5 text-xs font-bold text-ember-600"><RotateCcw className="h-3.5 w-3.5"/>Boost again</button>}</div>)}{campaigns.length===0&&<p className="text-sm text-graphite-500">No campaigns yet.</p>}</div></section></div></div>
}
